c.starter_code:
#include <stdio.h>
#include <string.h>

int main(void) {
    int n, q;
    scanf("%d", &n);
    scanf("%d", &q);
    int prefix[201] = {0};
    for (int i = 0; i < n; i++) {
        int value;
        scanf("%d", &value);
        prefix[i + 1] = prefix[i] + value;
    }
    for (int i = 0; i < q; i++) {
        int l, r;
        scanf("%d", &l);
        scanf("%d", &r);
        int before = l > 0 ? l - 1 : 0;
        printf("%d ", (prefix[r + 1] - prefix[before]));
    }
    printf("\n");
    return 0;
}

