#include <stdio.h>
#include <string.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int a[200] = {0};
    int right = 0;
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
        right += a[i];
    }
    int left = 0;
    int count = 0;
    for (int i = 0; i < n; i++) {
        if (left == right) {
            count++;
        }
        right -= a[i];
        left += a[i];
    }
    printf("%d ", (count));
    printf("\n");
    return 0;
}

