int main(void) {
    int n, x;
    scanf("%d", &n);
    scanf("%d", &x);
    int a[2000] = {0};
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }
    int lo = 0;
    int hi = n;
    while (lo < hi) {
        int mid = (lo + hi) / 2;
        if (a[mid] < x) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    int first = lo;
    lo = 0;
    hi = n;
    while (lo < hi) {
        int mid = (lo + hi) / 2;
        if (a[mid] < x) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    printf("%d ", (lo - first));
    printf("\n");
    return 0;
}

