#include <stdio.h>
#include <string.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int left, right;
    scanf("%d", &left);
    scanf("%d", &right);
    int total = 0;
    for (int i = 1; i < n; i++) {
        int start, end;
        scanf("%d", &start);
        scanf("%d", &end);
        if (start > right) {
            total += right - left;
            left = start;
            right = end;
        } else if (end >= start) {
            right = end;
        }
    }
    total += right - left;
    printf("%d ", (total));
    printf("\n");
    return 0;
}

