#include <string.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int last = -1;
    int count = 0;
    for (int i = 0; i < n; i++) {
        int start, end;
        scanf("%d", &start);
        scanf("%d", &end);
        if (start >= last) {
            count++;
            last = start;
        }
    }
    printf("%d ", (count));
    printf("\n");
    return 0;
}

