#include <stdio.h>
#include <string.h>

int main(void) {
    int cap, q;
    scanf("%d", &cap);
    scanf("%d", &q);
    int queue[32] = {0};
    int head = 0;
    int tail = 0;
    int count = 0;
    int rejected = 0;
    for (int i = 0; i < q; i++) {
        int op, k;
        scanf("%d", &op);
        scanf("%d", &k);
        if (op == 1) {
            int accept = count + k <= cap && tail + k <= cap ? 1 : 0;
            if (accept == 0) {
                rejected++;
            }
            for (int j = 0; j < k; j++) {
                int value;
                scanf("%d", &value);
                if (accept == 1) {
                    queue[tail] = value;
                    tail = (tail + 1) % cap;
                    count++;
                }
            }
        } else {
            int take = k < count ? k : count;
            head = (head + take) % cap;
            count -= take;
        }
    }
    printf("%d ", (rejected));
    printf("%d ", (count));
    for (int i = 0; i < count; i++) {
        printf("%d ", (queue[(head + i) % cap]));
    }
    printf("\n");
    return 0;
}

