    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d", &u);
        scanf("%d", &v);
        edge[u * 16 + v] = 1;
        edge[v * 16 + u] = 1;
    }
    for (int v = 0; v < n; v++) {
        distance[v] = -1;
    }
    int head = 0;
    int tail = 1;
    queue[0] = s;
    distance[s] = 0;
    ways[s] = 1;
    while (head < tail) {
        int u = queue[head++];
        for (int v = 0; v < n; v++) {
            if (edge[u * 16 + v] != 0) {
                if (distance[v] == -1) {
                    distance[v] = distance[u] + 1;
                    ways[v] = ways[u];
                    queue[tail++] = v;
                } else if (distance[v] == distance[u] + 1) {
                    ways[v] = ways[u];
                }
            }
        }
    }
    for (int v = 0; v < n; v++) {
        printf("%d ", (ways[v]));
    }
    printf("\n");
    return 0;
}

