int main(void) {
    int n, m, k;
    scanf("%d", &n);
    scanf("%d", &m);
    scanf("%d", &k);
    int edge[1024] = {0};
    int owner[32] = {0};
    int distance[32] = {0};
    int queue[32] = {0};
    for (int i = 0; i < n; i++) {
        owner[i] = -1;
    }
    int head = 0;
    int tail = 0;
    for (int i = 0; i < k; i++) {
        int s;
        scanf("%d", &s);
        owner[s] = s;
        queue[tail++] = s;
    }
    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d", &u);
        scanf("%d", &v);
        edge[u * 32 + v] = 1;
        edge[v * 32 + u] = 1;
    }
    int best = 1000000;
    while (head < tail) {
        int u = queue[head++];
        for (int v = 0; v < n; v++) {
            if (edge[u * 32 + v] != 0) {
                if (owner[v] == -1) {
                    owner[v] = owner[u];
                    distance[v] = distance[u] + 1;
                    queue[tail++] = v;
                } else if (owner[v] != owner[u]) {
                    int candidate = distance[u] + distance[v];
                    if (candidate < best) {
                        best = candidate;
                    }
                }
            }
        }
    }
    printf("%d ", (best == 1000000 ? -1 : best));
    printf("\n");
    return 0;
}

