        int accepted = 0;
        for (int i = 0; i < q; i++) {
            int candidate;
            candidate = scanner.nextInt();
            int distance = (candidate - current + 256) % 256;
            if (distance > 0 && distance < 128) {
                current = candidate;
                accepted++;
            }
        }
        System.out.print((current) + " ");
        System.out.print((accepted) + " ");
        System.out.println();
    }
}

