#include <stdio.h>
#include <string.h>

int main(void) {
    int n, amount;
    scanf("%d", &n);
    scanf("%d", &amount);
    int coins[5] = {0};
    int ways[31] = {0};
    for (int i = 0; i < n; i++) {
        scanf("%d", &coins[i]);
    }
    ways[0] = 1;
    for (int total = 1; total <= amount; total++) {
        for (int i = 0; i < n; i++) {
            if (coins[i] <= total) {
                ways[total] += ways[total - coins[i]];
            }
        }
    }
    printf("%d ", (ways[amount]));
    printf("\n");
    return 0;
}

